def test_run_pro_rata_split_matches_multiplier_ratio(session, service):
    model = make_model(session, name="Zero")
    user_a = make_user(session, email="a@example.com")
    user_b = make_user(session, email="b@example.com")
    period = make_confirmed_period(session)
    make_snapshot(session, period=period, model=model, user=user_a, multiplier=3)
    make_snapshot(session, period=period, model=model, user=user_b, multiplier=2)
    make_order(session, trade_date="20260603", model="Zero", proceeds=100)

    run = service.run(trigger=RunTrigger.MANUAL, actor=None)

    cells = {c.user_id: c for c in session.query(PostTradeAllocation).filter_by(run_id=run.id)}
    assert cells[user_a.id].allocated == Decimal("60")
    assert cells[user_b.id].allocated == Decimal("40")
    assert cells[user_a.id].pct == Decimal("60.000")
    assert cells[user_b.id].pct == Decimal("40.000")


