# --- Atomicity / rollback safety --------------------------------------------------


def test_run_exception_before_commit_leaves_orders_unmarked(session, service, monkeypatch):
    model = make_model(session, name="Zero")
    user = make_user(session)
    period = make_confirmed_period(session)
    make_snapshot(session, period=period, model=model, user=user, multiplier=1)
    order = make_order(session, trade_date="20260603", model="Zero", proceeds=100)
    session.commit()  # seed data must be committed — run()'s own rollback is a savepoint,
    # not a fresh session; without this, session.rollback() below would also wipe the arrange step.

    def _boom(*args, **kwargs):
        raise RuntimeError("simulated failure mid-run")

    monkeypatch.setattr(service.repo, "write_cells", _boom)

    with pytest.raises(RuntimeError):
        service.run(trigger=RunTrigger.MANUAL, actor=None)

    session.rollback()
    session.refresh(order)
    assert order.allocated_run_id is None
    assert session.query(PostTradeAllocation).count() == 0


def test_run_after_rollback_is_safely_retryable(session, service, monkeypatch):
    model = make_model(session, name="Zero")
    user = make_user(session)
    period = make_confirmed_period(session)
    make_snapshot(session, period=period, model=model, user=user, multiplier=1)
    make_order(session, trade_date="20260603", model="Zero", proceeds=100)
    session.commit()  # see note in test_run_exception_before_commit_leaves_orders_unmarked

    original_write_cells = PostTradeAllocationRepository.write_cells
    call_count = {"n": 0}

    def _fail_once(self, rows):
        call_count["n"] += 1
        if call_count["n"] == 1:
            raise RuntimeError("simulated failure")
        return original_write_cells(self, rows)

    monkeypatch.setattr(PostTradeAllocationRepository, "write_cells", _fail_once)

    with pytest.raises(RuntimeError):
        service.run(trigger=RunTrigger.MANUAL, actor=None)
    session.rollback()

    retry_run = service.run(trigger=RunTrigger.MANUAL, actor=None)
    assert retry_run.status == RunStatus.COMPLETED.value
    assert retry_run.grand_total == Decimal("100")


# --- Period boundary filter -----------------------------------------------------


def test_run_excludes_orders_ingested_before_period_confirmed_at(session, service):
    from datetime import datetime, timedelta, timezone

    model = make_model(session, name="Zero")
    user = make_user(session)
    confirmed_at = datetime.now(timezone.utc) - timedelta(hours=1)
    period = make_confirmed_period(session, confirmed_at=confirmed_at)
    make_snapshot(session, period=period, model=model, user=user, multiplier=1)
    # ponytail: old order ingested before period confirmation — should be skipped
    make_order(
        session, trade_date="20260603", model="Zero", proceeds=100,
        ingested_at=confirmed_at - timedelta(hours=2),
    )
    make_order(
        session, trade_date="20260603", model="Zero", proceeds=50,
        ingested_at=confirmed_at + timedelta(minutes=30),
    )

    run = service.run(trigger=RunTrigger.MANUAL, actor=None)

    assert run.grand_total == Decimal("50")


